const readLocal=(key,def)=>{try{return JSON.parse(localStorage.getItem('forma_'+key))??def}catch{return def}};
const writeLocal=(key,value)=>localStorage.setItem('forma_'+key,JSON.stringify(value));
let currentUser=readLocal('user',null);
function account(){window.FormaCommerce?.account();}

function getReviews(id){return readLocal('reviews_'+id,[])}
function reviewHTML(p){const items=getReviews(p.id);return `<section class="review-section"><div class="review-heading"><div><h3>Відгуки покупців</h3><p>${items.length?items.length+' відгуків':'Ще немає відгуків. Залиште перший!'}</p></div><span class="review-pill">★ ${p.rating} — огляд товару</span></div><div class="review-list">${items.map(r=>`<article class="review-card"><div><strong>${esc(r.name)}</strong><span class="stars">${'★'.repeat(r.stars)}${'☆'.repeat(5-r.stars)}</span></div><small>${esc(r.date)}</small><p>${esc(r.body)}</p></article>`).join('')}</div>${currentUser?`<form id="reviewForm" class="review-form"><h3>Написати відгук</h3><p class="muted">Публікація доступна лише у вашому браузері.</p>${window.FormaRatingUI.markup()}<label>Ваш відгук<textarea name="body" rows="4" minlength="10" maxlength="1200" required placeholder="Поділіться враженнями про товар…"></textarea></label><button class="btn" type="submit">Опублікувати відгук</button></form>`:`<div class="review-login"><p>Щоб написати відгук, увійдіть у ваш акаунт.</p><a href="#/account" class="btn">Увійти в акаунт</a></div>`}</section>`}

function info(title,body){app.innerHTML=`<div class="container info-page">${crumb(title)}<h1>${title}</h1>${body}</div>`}
function checkout(){window.FormaCommerce?.checkout(cart,P);}

function updateCounts(){$('#cartCount').textContent=Object.values(cart).reduce((a,b)=>a+b,0);$('#favCount').textContent=favs.length;$('#year').textContent=new Date().getFullYear()}
function add(id,n=1,colorChoice=null){const p=P.find(x=>x.id===id);if(!p)return;
 const chosen=colorChoice||cartColors[id]||(p.availableColors?.[0]||p.color||'');
 if(cart[id]&&cartColors[id]&&cartColors[id]!==chosen){toast('Товар уже в кошику в іншому кольорі. Видаліть його, щоб обрати інший.');return false}
 cartColors[id]=chosen;cart[id]=Math.min(p.stock,(cart[id]||0)+n);save();toast('Товар додано до кошика');return true;}

function drawer(){const ids=Object.keys(cart).filter(id=>cart[id]&&P.some(p=>p.id==id)),sum=ids.reduce((n,id)=>n+P.find(p=>p.id==id).price*cart[id],0);$('#drawer').innerHTML=`<div class="drawer-head"><h2>Ваш кошик (${ids.reduce((n,id)=>n+cart[id],0)})</h2><button class="close" id="closeDrawer" aria-label="Закрити">×</button></div><div class="drawer-body">${ids.length?ids.map(id=>{const p=P.find(x=>x.id==id);return `<div class="cart-line">${pic(p)}<div><a href="#/product/${p.slug}"><strong>${esc(p.name)}</strong></a><small>${money(p.price)} × ${cart[id]}${cartColors[id]?` · ${esc(cartColors[id])}`:''}</small><div class="qty"><button data-cartminus="${id}">−</button><span>${cart[id]}</span><button data-cartplus="${id}">+</button></div><button data-remove="${id}">Видалити</button></div></div>`}).join(''):`<div class="empty fh-cart-empty"><div class="fh-empty-icon" aria-hidden="true"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9V6a6 6 0 0 1 12 0v3"/><path d="M3.5 9h17l-1.4 12H4.9L3.5 9Z"/><path d="M9 13h.01M15 13h.01"/></svg></div><h3>У кошику поки порожньо</h3><p>Обирайте меблі й декор — ми збережемо все тут.</p><a href="#/catalog" class="btn">Перейти до товарів <span>↗</span></a></div>`}</div>${ids.length?`<div class="drawer-foot"><div class="totals"><span>Разом</span><span>${money(sum)}</span></div><p class="muted">Спосіб і вартість доставки визначаються під час оформлення.</p><a href="#/checkout" class="btn" id="checkoutGo" style="display:block;text-align:center">Оформити замовлення →</a></div>`:''}`;$('#overlay').classList.remove('hidden');$('#drawer').classList.add('open');$('#drawer').setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}
function closeDrawer(){$('#overlay').classList.add('hidden');$('#drawer').classList.remove('open');$('#drawer').setAttribute('aria-hidden','true');document.body.style.overflow=''}
let toastTimer;function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}

function aboutBrand(){app.innerHTML=`<div class="container info-page brand-story">${crumb('Про Forma Home')}<span class="eyebrow">ПРО МАГАЗИН</span><h1>Forma Home — простір для життя</h1><p class="lead">Меблі, обідні столи, стільці, килими й декор — продумані рішення для затишного дому.</p><div class="story-stats"><div><strong>${P.length}</strong><span>позицій каталогу</span></div><div><strong>${categories.length}</strong><span>категорій</span></div><div><strong>Forma</strong><span>власна доставка</span></div></div><h2>Наша ідея</h2><p>Forma Home поєднує різні напрямки облаштування дому: від диванів і килимів до обідніх столів, освітлення та декору. Каталог допомагає порівнювати матеріали, розміри, кольори й комплектації в одному місці.</p><h2>Доставка та складання</h2><p>Forma Home працює у форматі онлайн-каталогу без торговельних залів. Умови доставки та складання зазначаються під час оформлення замовлення і потребують остаточного узгодження.</p><a class="btn" href="#/delivery">Умови доставки →</a></div>`}

